{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The ALB listener is using HTTP protocol, which is insecure and can expose data to eavesdropping."
    },
    {
      "check_id": "CKV_AWS_103",
      "title": "Ensure that load balancer is using at least TLS 1.2",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The ALB listener is not using TLS, so the TLS version is not applicable, but changing the protocol to HTTPS will require setting a TLS version."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_policy        = \"ELBSecurityPolicy-TLS13-1-2-2021-06\"\n  certificate_arn   = \"arn:aws:acm:REGION:ACCOUNT_ID:certificate/CERTIFICATE_ID\"\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}",
  "fix_summary": "Changed the ALB listener protocol from HTTP to HTTPS, updated the port to 443, and added an SSL policy and certificate ARN. You must replace REGION, ACCOUNT_ID, and CERTIFICATE_ID with your actual AWS region, account ID, and ACM certificate ID."
}
